    "id": "pin-pele-volcano",
    "title_th": "เปเล่ (เทพีแห่งไฟและภูเขาไฟคิลาเวอา)",
    "title_en": "Pele: The Goddess of Fire & Volcanoes of Kīlauea",
    "category": "sacred",
    "province_th": "ฮาวาย",
    "province_en": "Hawaii",
