    "id": "pin-dakuwaqa",
    "title_th": "ดาคูวากา (เทพเจ้าฉลามผู้พิทักษ์แห่งแนวปะการังฟิจิ)",
    "title_en": "Dakuwaqa: The Shark God Guardian of the Fijian Reefs",
    "category": "sacred",
    "province_th": "คากาวโดรฟ",
