    "id": "pin-loveland-frogman",
    "title_th": "มนุษย์กบแห่งเลิฟแลนด์ (อมนุษย์สะเทินน้ำสะเทินบกแห่งโอไฮโอ)",
    "title_en": "The Loveland Frogman of Ohio",
    "category": "monster",
    "province_th": "โอไฮโอ (สหรัฐอเมริกา)",
    "province_en": "Ohio (USA)",
    "district_th": "เมืองเลิฟแลนด์ ริมแม่น้ำลิตเติลไมอามี",
    "district_en": "Loveland, Little Miami River",
    "lat": 39.2689,
    "lng": -84.2638,
    "story_th": "สิ่งมีชีวิตกึ่งมนุษย์กึ่งกบยืนสองขาสูงราว 1.2 เมตร ผิวหนังเป็นเกล็ดเปียกชื้น มีพังผืดที่มือและเท้า และมีดวงตากลมโตโปนเรืองแสง เคยถูกพบเห็นยืนรวมกลุ่มกันอยู่ใต้สะพานข้ามแม่น้ำลิตเติลไมอามีในยามดึก",
    "story_en": "A legendary bipedal humanoid with frog-like features standing four feet tall with webbed appendages, sighted along the Little Miami River by multiple police officers in 1955 and 1972.",
    "folklore_history_th": "มีรายงานการพบเห็นครั้งแรกในปี 1955 โดยนักธุรกิจ และต่อมาในปี 1972 เจ้าหน้าที่ตำรวจสองนายได้พบเห็นและรายงานอย่างเป็นทางการ จนกลายเป็นสัญลักษณ์และตำนานประจำเมืองเลิฟแลนด์",
    "folklore_history_en": "First reported in 1955 and reaffirmed in 1972 when two Loveland police officers observed the creature climbing over a guardrail into the river.",
    "taboos_th": "หากเดินริมตลิ่งแม่น้ำลิตเติลไมอามียามค่ำคืนแล้วได้ยินเสียงกระโดดน้ำหนักๆ ห้ามส่องไฟฉายไล่ตามตัว",
    "taboos_en": "Do not illuminate shadowed riverbanks along Little Miami if heavy splashing echoes from under bridges.",
    "image_url": "https://images.unsplash.com/photo-1544717305-2782549b5136?auto=format&fit=crop&w=1200&q=80",
    "sound_preset": "water_spirit",
