    "lat": 34.2185,
    "lng": -80.2448,
    "story_th": "อมนุษย์เลื้อยคลานสูงกว่า 2 เมตร ผิวหนังสีเขียวขรุขระ มีกรงเล็บแหลมคม 3 นิ้วที่แข็งแรงพอจะฉีกแผ่นเหล็กรถยนต์ พุ่งเข้าจู่โจมรถของชาวบ้านที่จอดเปลี่ยนยางริมหนองน้ำสเคปออร์ในคืนฤดูร้อน",
    "story_en": "A seven-foot bipedal reptile with green scaly skin and three clawed digits on each hand, infamous for attacking moving vehicles and mauling car fenders near Scape Ore Swamp.",
    "folklore_history_th": "คริสโตเฟอร์ เดวิส วัยรุ่นท้องถิ่นรายงานการถูกจู่โจมในปี 1988 และมีรอยขูดขีดลึกบนหลังคารถยนต์ ต่อมามีรายงานการพบรอยเท้าสามนิ้วยาว 14 นิ้วในโคลน",
    "folklore_history_en": "Burst into national prominence in 1988 after teen Christopher Davis suffered claw scratches across his car roof, followed by confirmed 14-inch three-toed mud tracks.",
    "taboos_th": "ห้ามจอดรถริมถนนตัดผ่านหนองน้ำสเคปออร์หลังพระอาทิตย์ตกดิน และห้ามลงไปสำรวจรอยเท้าในดงปรือ",
    "taboos_en": "Never halt a vehicle along Scape Ore Swamp after dusk, as clawed thrashing signals an impending ambush.",
