    "title_en": "The Pope Lick Monster (Goatman of the Trestle)",
    "category": "monster",
    "province_th": "เคนทักกี (สหรัฐอเมริกา)",
    "province_en": "Kentucky (USA)",
    "district_th": "สะพานรถไฟโปปลิค ลุยส์วิลล์",
    "district_en": "Pope Lick Trestle, Louisville",
    "lat": 38.1965,
    "lng": -85.4962,
    "story_th": "อสูรลูกผสมกึ่งมนุษย์กึ่งแพะ มีเขางุ้มและขนสีเข้ม สถิตอยู่ใต้สะพานทางรถไฟสูงชัน เล่าขานว่ามันใช้เสียงกระซิบสะกดจิตเลียนแบบเสียงคนที่เหยื่อรัก เพื่อล่อลวงให้ผู้คนเดินขึ้นไปบนรางรถไฟสูงจนถูกรถไฟชนตกสะพาน",
    "story_en": "A grotesque human-goat hybrid haunting the high Pope Lick train trestle in Louisville, rumored to utilize telepathic hypnosis or mimicry to lure trespassers into oncoming locomotives.",
    "folklore_history_th": "เป็นตำนานเมืองที่อันตรายที่สุดแห่งหนึ่งของสหรัฐฯ เนื่องจากมีวัยรุ่นจำนวนมากพยายามปีนสะพานรถไฟโปปลิคเพื่อพิสูจน์ความกล้าจนเกิดอุบัติเหตุเสียชีวิตจริงมาหลายทศวรรษ",
    "folklore_history_en": "A morbid urban legend responsible for actual fatalities over decades as curious thrill-seekers traversed the dangerous 90-foot railway trestle.",
    "taboos_th": "ห้ามเดินขึ้นไปบนรางรถไฟโปปลิคเด็ดขาด และอย่าตอบรับเสียงผิวปากหรือเสียงกระซิบเรียกชื่อจากใต้สะพาน",
    "taboos_en": "Never step foot onto the elevated Pope Lick railway trestle; dismiss hypnotic vocal mimicry coming from the ravine.",
