    "id": "pin-fresno-nightcrawlers",
    "title_th": "ไนท์ครอว์เลอร์แห่งเฟรสโน (อมนุษย์ขากางเกงขาวเร่ร่อน)",
    "title_en": "The Fresno Nightcrawlers of California",
    "category": "legend",
    "province_th": "แคลิฟอร์เนีย (สหรัฐอเมริกา)",
    "province_en": "California (USA)",
    "district_th": "เมืองเฟรสโนและอุทยานโยเซมิตี",
