    "lat": 36.7468,
    "lng": -119.7726,
    "story_th": "สิ่งมีชีวิตลึกลับที่มีเพียงท่อนขาสีขาวยาวคู่หนึ่งและหัวขนาดเล็ก ไร้ลำตัวและแขน เคลื่อนที่ด้วยท่วงท่าย่องเบาราวกับล่องลอยในอากาศ มักถูกจับภาพได้โดยกล้องวงจรปิดขณะเดินข้ามสนามหญ้าในยามดึก",
    "story_en": "An enigmatic cryptid appearing as a pair of slender white legs connected to an eyeless upper node, captured walking silently across surveillance feeds in Fresno and Yosemite.",
    "folklore_history_th": "ปรากฏครั้งแรกจากฟุตเทจกล้องวงจรปิดของบ้านหลังหนึ่งในเฟรสโนเมื่อปี 2007 และต่อมาถูกบันทึกได้อีกครั้งในอุทยานแห่งชาติโยเซมิตีปี 2011 ชนพื้นเมืองอเมริกันเชื่อว่าเป็นสิ่งมีชีวิตจากมิติอื่นที่รักสงบ",
    "folklore_history_en": "First recorded on home security video in 2007 and verified in 2011 Yosemite footage, connected to Native American folklore regarding peaceful otherworldly travelers.",
    "taboos_th": "หากพบเห็นเงาสีขาวเดินข้ามสวนยามดึก ห้ามส่งเสียงตกใจหรือขว้างปาสิ่งของเข้าใส่ จงเฝ้ามองอย่างเงียบเชียบ",
    "taboos_en": "Do not chase or harass the walking white silhouettes; they move passively across terrestrial terrain without malice.",
    "image_url": "https://images.unsplash.com/photo-1509114397022-ed747cca3f65?auto=format&fit=crop&w=1200&q=80",
    "sound_preset": "creepy_wind",
