    "lat": 41.7123,
    "lng": -72.6082,
    "story_th": "สัตว์ร้ายลึกลับที่ผสมผสานระหว่างสิงโตภูเขา เสือดาว และหมาป่า ขนสีน้ำตาลเข้ม ส่งเสียงกรีดร้องแหลมสูงโหยหวนดั่งผู้หญิงกำลังถูกทำร้าย ออกล่าสังหารฝูงแกะและสัตว์เลี้ยงในฟาร์ม",
    "story_en": "A terrifying predator described as a combination of panther, bear, and wolf, famed for piercing wails that paralyzed New England farmsteads in 1939.",
    "folklore_history_th": "ในฤดูหนาวปี 1939 สัตว์เลี้ยงในกลาสตันเบอรีถูกสังหารไปนับสิบตัว มีการระดมพรานป่าและสุนัขดมกลิ่นนับร้อยออกตามล่า แต่ไม่เคยจับตัวได้จนได้รับฉายาว่ากลาวาคัส",
    "folklore_history_en": "Triggered a massive organized hunt in 1939 involving state troopers and hunting hounds across Connecticut woodlands.",
    "taboos_th": "หากได้ยินเสียงผู้หญิงกรีดร้องโหยหวนในดงไม้หลังบ้านยามดึก ห้ามเปิดประตูออกไปตามหาเสียง",
    "taboos_en": "Never investigate human-sounding shrieks resonating from Glastonbury apple orchards after dark.",
