    "lng": -77.1945,
    "story_th": "สัตว์ประหลาดตัวเล็กผิวหนังเหี่ยวย่นหย่อนยานและเต็มไปด้วยหูด มันรู้ตัวว่าน่าเกลียดจึงคอยหลบซ่อนตัวและร้องไห้น้ำตาไหลพรากอยู่ตลอดเวลา หากถูกมนุษย์จับได้ มันจะร้องไห้หนักจนละลายร่างตัวเองกลายเป็นหยดน้ำตาและฟองสบู่",
