    "folklore_history_th": "บันทึกในหนังสือ 'Fearsome Creatures of the Lumberwoods' ปี 1910 เล่าขานโดยคนตัดไม้ชาวเพนซิลเวเนียที่มักได้ยินเสียงสะอึกสะอื้นในดงต้นเฮมล็อก",
