    "story_th": "อูฐยักษ์สีแดงชาดที่มีโครงกระดูกมนุษย์ไร้หัวผูกติดอยู่บนหลังด้วยสายรัดหนัง ควบตะบึงผ่านทะเลทรายและบุกทำลายค่ายพักแรมของคาวบอย ทิ้งรอยเท้าขนาดมหึมาและขนสีแดงไว้เป็นปริศนา",
    "story_en": "A feral reddish camel carrying the headless skeleton of a strapped human rider across the Arizona frontier, terrorizing ranchers in the 1880s.",
    "folklore_history_th": "มีรากฐานมาจากโครงการฝูงอูฐทดลองของกองทัพสหรัฐฯ ในช่วงทศวรรษ 1850 ต่อมาอูฐตัวนี้ถูกยิงตายในปี 1893 โดยชาวไร่ และพบรอยแผลเป็นจากสายรัดหนังจริง",
    "folklore_history_en": "Escaped from the experimental US Camel Corps, turning into a grim desert ghost legend until it was shot by rancher Mizoo Hastings in 1893.",
    "taboos_th": "หากได้ยินเสียงฝีเท้าอูฐควบตะลุยกลางทะเลทรายแอริโซนายามค่ำ ห้ามโผล่ศีรษะออกจากที่พัก",
    "taboos_en": "Do not step outside desert tents if heavy hoofbeats trample through cactus groves under moonlight.",
    "image_url": "https://images.unsplash.com/photo-1509114397022-ed747cca3f65?auto=format&fit=crop&w=1200&q=80",
    "sound_preset": "creepy_wind",
