    "story_th": "สิ่งมีชีวิตกึ่งงูกึ่งค้างคาวมีปีกขนนก ลำตัวยาวเป็นเกล็ดหนา สามารถสะกดสายตาเหยื่อด้วยดวงตาสีแดงเพลิงจนขยับตัวไม่ได้ ก่อนจะโผลงมาดูดเลือดมนุษย์และแกะจนแห้งสนิท",
    "story_en": "A fearsome flying serpent of Mapuche mythology with bat-like wings and paralyzing red gaze, capable of draining the blood of sheep and lone wanderers.",
    "folklore_history_th": "มีรากฐานลึกซึ้งในวัฒนธรรมชาวมาปูเช เชื่อว่าเปวเชนสามารถจำแลงกายเป็นกิ่งไม้แห้งเพื่อดักรอเหยื่อ และมีเพียงหมอผีมาชิ (Machi) เท่านั้นที่สามารถขับไล่มันได้",
    "folklore_history_en": "Deeply rooted in Mapuche tribal culture; only a female shaman (Machi) possessed the spiritual rituals capable of dispelling a resident Peuchen.",
