    "district_en": "Eastern Amazon & Xingu River",
    "lat": -5,
    "lng": -45,
    "story_th": "สัตว์ประหลาดกระหายเลือดที่มีลำตัวล่ำสันคล้ายมนุษย์ขนดก แต่มีหัวและจมูกยาวยื่นคล้ายตัวกินมดยักษ์ เท้ากลมไม่มีนิ้วคล้ายก้นขวด ออกล่าเหยื่อด้วยการใช้ปากดูดกินสมองของลูกหมา ลูกวัว และมนุษย์ที่พลัดหลง",
    "story_en": "A vicious monster of indigenous Brazilian folklore having the muscular torso of a human, hoof-like rounded feet, and the elongated snout of a giant anteater used to pierce skulls.",
    "folklore_history_th": "ชนเผ่าพื้นเมืองในรัฐมารันเยาและปาราเชื่อว่าคาเปโลโบเกิดจากมนุษย์ชราที่กลายร่างเป็นอมนุษย์หลังจากใช้ชีวิตโดดเดี่ยวในป่าลึกนานเกินไป",
    "folklore_history_en": "Rooted in tribal traditions of Maranhao, viewed as the horrific outcome of elderly hermits transformed through dark forest spirits.",
    "taboos_th": "จุดอ่อนเดียวของคาเปโลโบคือสะดือ หากเผชิญหน้าให้เล็งยิงหรือแทงเข้าที่กึ่งกลางหน้าท้องเท่านั้น",
    "taboos_en": "The only lethal vulnerability of the Capelobo is its navel; standard arrows cannot pierce its reinforced hide.",
    "image_url": "https://images.unsplash.com/photo-1518709268805-4e9042af9f23?auto=format&fit=crop&w=1200&q=80",
    "sound_preset": "jungle_curse",
