    "title_th": "อมนุษย์จระเข้แห่งเพลาโต (โฮมเบรไกมันแห่งแม่น้ำมักดาเลนา)",
    "title_en": "The Alligator Man of Plato (El Hombre Caiman)",
    "category": "legend",
