    "id": "pin-trow-orkney",
    "title_th": "เดอะโทรว (ภูตแคระนักดนตรีใต้ดินแห่งหมู่เกาะออร์คนีย์)",
    "title_en": "The Trows of Orkney and Shetland",
    "category": "legend",
    "province_th": "ออร์คนีย์ (สหราชอาณาจักร)",
    "province_en": "Orkney Islands (United Kingdom)",
