    "title_en": "The Brown Lady of Raynham Hall",
    "category": "ghost",
    "province_th": "นอร์ฟอล์ก (สหราชอาณาจักร)",
    "province_en": "Norfolk (United Kingdom)",
    "district_th": "คฤหาสน์เรย์นแฮมฮอลล์",
    "district_en": "Raynham Hall, Fakenham",
    "lat": 52.7917,
    "lng": 0.7892,
    "story_th": "วิญญาณเลดี้โดโรธี วอลโพล ในชุดเดรสผ้าซาตินสีน้ำตาลที่ถูกถ่ายภาพติดขณะลอยลงมาจากบันไดไม้โอ๊คในปี 1936 ได้รับการยกย่องให้เป็นหนึ่งในภาพถ่ายติดวิญญาณที่โด่งดังและคลาสสิกที่สุดในโลก",
    "story_en": "The ghost of Lady Dorothy Walpole, haunting Raynham Hall and famously captured descending the grand staircase in a celebrated 1936 photograph for Country Life magazine.",
    "folklore_history_th": "เลดี้โดโรธีเสียชีวิตอย่างมีเงื่อนงำในปี 1726 โดยถูกสามีขังไว้ในคฤหาสน์หลังจับได้ว่านอกใจ มีพยานพบเห็นวิญญาณของเธอนับแต่ศตวรรษที่ 19 รวมถึงกษัตริย์จอร์จที่ 4",
    "folklore_history_en": "Died under mysterious circumstances in 1726 after being locked in her chambers, sighted by luminaries including King George IV.",
    "taboos_th": "ห้ามยืนจ้องบันไดใหญ่เรย์นแฮมฮอลล์หลังเที่ยงคืน หากได้ยินเสียงลากชายกระโปรงผ้าซาตินให้รีบถอยออกมา",
    "taboos_en": "Never linger at the foot of Raynham's oak staircase after midnight when faint rustling satin whispers along steps.",
    "image_url": "https://images.unsplash.com/photo-1509114397022-ed747cca3f65?auto=format&fit=crop&w=1200&q=80",
    "sound_preset": "whisper",
    "views_count": 16,
    "is_published": 1,
