    "lat": 55.8553,
    "lng": -3.1601,
    "story_th": "ประติมากรรมแกะสลักหินรูปใบหน้าบุรุษโบราณที่มีกิ่งไม้และใบโอ๊คงอกออกมาจากปาก จมูก และดวงตา สถิตตามเสาหินและเพดานโบสถ์โกธิกยุโรป สัญลักษณ์แห่งการเกิดใหม่และพลังลี้ลับของธรรมชาติ",
    "story_en": "A primeval architectural motif depicting a human face woven from sprouting foliage, deeply embedded in medieval cathedrals and pagan renewal symbolism.",
    "folklore_history_th": "ปรากฏอย่างหนาแน่นในวิหารรอสลินอันลึกลับของสก็อตแลนด์กว่าร้อยจุด เชื่อมโยงกับตำนานอัศวินเทมพลาร์และความเชื่อเพแกนดั้งเดิมของชาวเคลต์",
    "folklore_history_en": "Heavily featured across Rosslyn Chapel, embodying the synthesis of pre-Christian pagan vegetative gods and medieval Christian architecture.",
    "taboos_th": "เมื่อเข้าชมวิหารรอสลิน ห้ามเอื้อมมือสัมผัสใบหน้ากรีนแมนที่แกะสลักเหนือเสานักเรียนช่าง (Apprentice Pillar)",
    "taboos_en": "Do not touch stone carvings of the foliated head upon sacred cathedral arches with defiling intent.",
