    "lat": 53.4808,
    "lng": -2.2426,
    "story_th": "พรายน้ำหญิงชราผิวสีเขียวซีด มีฟันแหลมคมยาวสีเขียวดั่งแหนเป็ด และผมยาวเปียกชื้น ซ่อนตัวอยู่ใต้พืชน้ำและจอกแหน เมื่อเด็กๆ ก้มมองผิวน้ำ เธอจะยื่นแขนยาวผอมแห้งขึ้นมาดึงขาลากลงไปกดน้ำ",
    "story_en": "A sinister river hag with green skin and needle-sharp teeth dwelling beneath floating duckweed, pulling careless children into watery graves.",
    "folklore_history_th": "นิทานพื้นบ้านของชาวอังกฤษตอนเหนือ ใช้เป็นเรื่องเล่าเตือนสติให้เด็กๆ ระมัดระวังไม่เข้าไปใกล้ริมคลอง ตลิ่งแม่น้ำลึก หรือบ่อโคลนดูดที่ปกคลุมด้วยแหนสีเขียว",
    "folklore_history_en": "A quintessential Northern English nursery bogey used by generations of parents to prevent children from drowning in weed-choked canals.",
    "taboos_th": "ห้ามก้มหน้าชะโงกมองผิวน้ำที่ถูกปกคลุมด้วยแหนเป็ดหนาทึบโดยเด็ดขาด",
    "taboos_en": "Never peer over riverbanks choked with thick duckweed mats, lest pale green talons grasp your collar.",
