    "lng": -2.0792,
    "story_th": "สุนัขปีศาจสีดำร่างยักษ์ขนาดเท่าลูกวัว ดวงตาสีแดงฉานดั่งถ่านคุ ลากโซ่เหล็กส่งเสียงครูดไปตามโขดหินชายฝั่งทะเลอ่าวบูเลย์ยามพายุพัดโหมกระหน่ำ",
    "story_en": "A monstrous black phantom hound the size of a heifer with glowing saucer-sized red eyes, patrolling the cliff paths of Bouley Bay dragging iron chains.",
    "folklore_history_th": "เรื่องเล่ามีมาหลายศตวรรษ ส่วนหนึ่งเชื่อว่ากลุ่มโจรลักลอบนำเข้าสินค้าเถื่อนในศตวรรษที่ 18 ได้แต่งเรื่องเสริมความน่ากลัวเพื่อไม่ให้ชาวบ้านและเจ้าหน้าที่ลงไปยังอ่าวบูเลย์ยามดึก",
    "folklore_history_en": "A legendary Channel Island spectral hound, reinforced by 18th-century smugglers who amplified ghost stories to keep coastal patrols away.",
    "taboos_th": "หากเดินริมหน้าผาอ่าวบูเลย์ยามค่ำแล้วได้ยินเสียงโซ่เหล็กครูดกับหิน ให้ยืนนิ่งและอย่าหันไปสบตากับดวงตาสีแดง",
    "taboos_en": "Freeze in place and avert gaze if metallic chains rattle along the storm-battered cliff tracks of Bouley Bay.",
