    "id": "pin-morbach-monster",
    "title_th": "อสูรแห่งมอร์บาค (มนุษย์หมาป่าตัวสุดท้ายแห่งเยอรมนี)",
    "title_en": "The Morbach Monster (Germany's Last Werewolf)",
    "category": "monster",
    "province_th": "ไรน์ลันด์-ฟัลทซ์ (เยอรมนี)",
    "province_en": "Rhineland-Palatinate (Germany)",
    "district_th": "เมืองมอร์บาค ฐานทัพอากาศฮุนส์รึค",
    "district_en": "Morbach & Hahn Air Base",
    "lat": 49.8167,
    "lng": 7.1167,
    "story_th": "มนุษย์หมาป่าร่างยักษ์ยืนสองขาที่มีขนสีเทาหนา สถิตอยู่ในป่าสนฮุนส์รึค มีจุดเชื่อมโยงกับเทียนไขศักดิ์สิทธิ์ในศาลเจ้าประจำหมู่บ้าน หากเทียนดับลง อสูรหมาป่าจะปรากฏตัวออกมาอาละวาดทันที",
    "story_en": "A legendary werewolf haunting the Hunsrück forests of Morbach, closely bound to a shrine candle that must never be permitted to burn out.",
    "folklore_history_th": "ในปี 1988 ทหารสหรัฐฯ ประจำฐานทัพมอร์บาครายงานการพบสิ่งมีชีวิตคล้ายหมาป่ายักษ์ยืนสองขาปีนรั้วกักกันความปลอดภัยสูง ซึ่งเกิดขึ้นในคืนเดียวกับที่เทียนในศาลเจ้าดับลงเพราะพายุพัด",
    "folklore_history_en": "Triggered a lockdown at the US Morbach Munitions Depot in 1988 when armed sentries observed an upright canine leaping a ten-foot security fence.",
    "taboos_th": "ห้ามปล่อยให้เทียนไขในศาลเจ้ามอร์บาคดับลงเด็ดขาด และอย่าเดินในป่าสนฮุนส์รึคยามค่ำคืนคนเดียว",
    "taboos_en": "The perpetual candle at the Morbach shrine must remain lit; an extinguished flame releases the prowling beast.",
    "image_url": "https://images.unsplash.com/photo-1509114397022-ed747cca3f65?auto=format&fit=crop&w=1200&q=80",
    "sound_preset": "creepy_wind",
