    "lat": 45.9237,
    "lng": 6.8694,
    "story_th": "สัตว์ในตำนานคล้ายเลียงผาหรือแพะภูเขา มีวิวัฒนาการพิเศษจนขาทั้งสองข้างมีความยาวไม่เท่ากัน (ขาซ้ายสั้นกว่าขาขวา หรือขวาสั้นกว่าขาซ้าย) เพื่อให้สามารถเดินเลาะตามแนวลาดชันของหน้าผาสูงชันได้โดยไม่ตกลงมา",
    "story_en": "A whimsical mythological creature of Alpine lore resembling an ibex whose left and right legs differ in length, allowing it to walk effortlessly along steep mountain slopes.",
    "folklore_history_th": "นิทานพื้นบ้านดั้งเดิมของชาวซาวอยและสวิส นิยมเล่าให้นักท่องเที่ยวฟังเพื่อล่อให้ออกไป 'ล่าดายู' ยามค่ำคืนด้วยการเป่านกหวีดข้างหลังเพื่อให้มันหันกลับมาจนเสียหลักสะดุดล้ม",
    "folklore_history_en": "A staple of Alpine rural culture; locals initiate gullible travelers into comical night hunts to startle the beast into turning around.",
    "taboos_th": "ห้ามเป่านกหวีดข้างหลังดายูขณะที่มันกำลังเดินเลาะหน้าผาสูงชัน",
    "taboos_en": "Never whistle behind an Alpine Dahu while it grazes along sheer rock ledges.",
