    "lat": 54.5444,
    "lng": -1.9261,
    "story_th": "พรายน้ำหญิงชราผมยาวสีเขียวคล้ายสาหร่าย อาศัยอยู่ในห้วงน้ำวนลึกของแม่น้ำทีส์ ฟองคลื่นสีขาวบนผิวน้ำถูกเรียกว่า 'Peg Powler's Suds' หากมีใครลงเล่นน้ำใกล้ฟองคลื่น เธอจะคว้าข้อเท้าลากลงสู่ก้นแม่น้ำ",
    "story_en": "A malicious water spirit with long green hair inhabiting the rapids of River Tees, dragging insolent bathers beneath swirling foam clusters.",
    "folklore_history_th": "ตำนานพื้นบ้านเก่าแก่ของเดอรัมและยอร์กเชียร์ บิดามารดามักใช้เตือนลูกหลานไม่ให้ลงไปเล่นน้ำในแม่น้ำทีส์ที่มีกระแสน้ำวนและแก่งหินลื่นไหลรวดเร็ว",
    "folklore_history_en": "A historic Northern English warning spirit whose signature surface foam warned children of hazardous river whirlpools.",
    "taboos_th": "ห้ามก้าวขาลงไปในบริเวณแม่น้ำทีส์ที่มีฟองคลื่นฟูฟ่องสีขาวคล้ายฟองสบู่",
    "taboos_en": "Keep clear of frothy foam patches known as Peg Powler's Suds drifting along rocky banks.",
