    "district_en": "Pennine Bogs & Leeds Canals",
    "lat": 53.8008,
    "lng": -1.5491,
    "story_th": "ปีศาจน้ำตัวเล็กสีเขียวซีด มีนิ้วมือเรียวยาวแหลมคมคล้ายกิ่งไม้แห้ง ซ่อนตัวอยู่ในกอดงกกกและโคลนดูดใต้น้ำ ใช้นิ้วยาวเหนียวหนึบคว้าจับเด็กที่ยื่นมือลงมาเล่นน้ำแล้วดึงจมลงสู่ใต้บึง",
    "story_en": "A bog demon of Yorkshire folklore with elongated sinewy fingers that snatch children into the depths of peat marshes.",
    "folklore_history_th": "ถูกบันทึกในเอกสารคติชนวิทยาอังกฤษมานานหลายศตวรรษ และมีชื่อเสียงระดับโลกเมื่อถูกนำไปดัดแปลงเป็นสัตว์วิเศษในวรรณกรรมแฟนตาซียุคใหม่",
    "folklore_history_en": "An ancient English marsh creature preserved in Yorkshire dialect and later popularized in contemporary folklore studies.",
    "taboos_th": "ห้ามยื่นมือลงไปกวักน้ำในบึงหนองน้ำที่เต็มไปด้วยดงอ้อและจอกแหนเป็ด",
    "taboos_en": "Never dip fingers into dark peaty waters where long reed-like shadows tremble beneath the surface.",
