    "lat": 46.6247,
    "lng": 14.3053,
    "story_th": "มังกรสองขาไร้ปีกขนาดยักษ์ ลำตัวคล้ายงูเกล็ดหนาสีเขียวเข้ม อาศัยอยู่ในหนองน้ำรอบทะเลสาบเวิร์ทเทอร์ซี ออกกินวัวควายและชาวบ้าน จนกระทั่งดยุกแห่งคารินเทียใช้อุบายผูกวัวเข้ากับโซ่เบ็ดขนาดใหญ่ล่อสังหารมังกรได้สำเร็จ",
    "story_en": "A legendary wingless two-legged dragon that terrorized the wetlands of Klagenfurt until slain by knights using a chain-bound bull as bait.",
    "folklore_history_th": "ตำนานการก่อตั้งเมืองคลาเกนฟวร์ท มีอนุสาวรีย์น้ำพุมังกรหินแกะสลัก 'Lindwurmbrunnen' ขนาดมหึมาตั้งตระหง่านอยู่กลางจัตุรัสเมืองตั้งแต่ปี 1590",
    "folklore_history_en": "Foundational legend of Klagenfurt; the city center has been graced by the famous monumental stone Lindwurm fountain since 1590.",
    "taboos_th": "ห้ามโยนเหรียญหรือสิ่งสกปรกลงในอ่างน้ำพุมังกรหินลินด์วอร์ม",
    "taboos_en": "Show reverence before the monumental stone dragon fountain in the central square of Klagenfurt.",
