    "id": "pin-berbalang-cagayan",
    "title_th": "เบอร์บาลัง (เผ่าพันธุ์กินศพมีปีกแห่งเกาะซูลู)",
    "title_en": "The Berbalangs of Cagayan de Sulu",
    "category": "monster",
