    "id": "pin-sigbin-philippines",
    "title_th": "ซิกบิน (สัตว์ประหลาดเงาเดินถอยหลังแห่งฟิลิปปินส์)",
    "title_en": "The Sigbin of the Visayas",
    "category": "monster",
