    "id": "pin-baak-assam",
    "title_th": "บาค (ผีน้ำสถิตบึงจับมนุษย์ขังใต้โคลนแห่งรัฐอัสสัม)",
    "title_en": "The Baak of Assam Wetlands",
    "category": "ghost",
    "province_th": "อัสสัม (อินเดีย)",
    "province_en": "Assam (India)",
    "district_th": "พื้นที่ชุ่มน้ำแม่น้ำพรหมบุตร เมืองกูวาฮาติ",
