    "lat": 26.1445,
    "lng": 91.7362,
    "story_th": "วิญญาณร้ายที่สิงสถิตอยู่ในบึงน้ำ ลำธาร และหนองน้ำแถบลุ่มน้ำพรหมบุตร ชื่นชอบการกินปลาดิบเป็นชีวิตจิตใจ มักทำร้ายคนหาปลา ลากร่างเหยื่อไปฝังซ่อนไว้ใต้โคลนตมก้นบึง และแปลงร่างสวมรอยเป็นเหยื่อกลับเข้าบ้าน",
    "story_en": "A malicious aquatic ghoul of Assamese folk tales lurking in marshlands, murdering fishermen, hiding their corpses in lake mud, and impersonating them at home.",
    "folklore_history_th": "นิทานพื้นบ้านดั้งเดิมของชาวอัสสัม เล่าขานต่อกันว่าหากคนหาปลาพกมีดฉีกหรืออุปกรณ์ที่ทำจากไม้ไผ่ผ่าซีก บาคจะไม่กล้าเข้าใกล้เพราะหวาดกลัวของมีคมและไม้ไผ่จักสาน",
    "folklore_history_en": "A prominent fixture in Assamese storytelling; folk remedies dictate keeping a torn fishnet or sharp bamboo knife to ward off the entity.",
    "taboos_th": "หากกลับมาจากหาปลาตอนดึกแล้วเห็นคนในครอบครัวมีพฤติกรรมกินปลาดิบอย่างมูมมามผิดปกติ ให้ระวังว่าอาจเป็นบาคจำแลงกายมา",
    "taboos_en": "Never consume fresh fish raw beside midnight waterways; carry woven bamboo splitters to repel a stalking Baak.",
    "image_url": "https://images.unsplash.com/photo-1544717305-2782549b5136?auto=format&fit=crop&w=1200&q=80",
    "sound_preset": "water_spirit",
