    "id": "pin-mu-onna-japan",
    "title_th": "มุอนนะ (วิญญาณสตรีไร้หน้าผู้พิทักษ์เด็กแห่งญี่ปุ่น)",
    "title_en": "Mu-onna (The Faceless Mother Spirit of Japan)",
    "category": "ghost",
