    "lat": 35.06,
    "lng": 135.83,
    "story_th": "วิญญาณหญิงสาวที่เกิดจากความโศกเศร้าของมารดาที่สูญเสียลูก ใบหน้าของเธอว่างเปล่าไร้ตา จมูก และปาก เธอจะคอยตามหาเด็กที่ถูกครอบครัวทอดทิ้งเพื่อนำไปโอบกอดและปกป้องไว้ในอ้อมอกอันอบอุ่นชั่วนิรันดร์",
    "story_en": "A sorrowful yokai originating from a mother who lost her child to famine, possessing no facial features and wandering to comfort neglected or lost children.",
    "folklore_history_th": "บันทึกในตำราโยไกโบราณสมัยเอโดะ แม้จะมีรูปลักษณ์ไร้หน้าที่ชวนสยดสยอง แต่มุอนนะกลับเป็นวิญญาณที่ไม่ทำร้ายมนุษย์ เว้นแต่ผู้ปกครองที่ทุบตีทำร้ายลูกของตนเอง",
    "folklore_history_en": "Featured in classic Edo-era yokai compendiums as a tragic, protective specter born of famine and grief.",
    "taboos_th": "ห้ามทอดทิ้งเด็กเล็กให้อยู่ตามลำพังในศาลเจ้าร้างยามค่ำคืน เพราะมุอนนะจะมารับตัวไปเป็นบุตรทิพย์",
    "taboos_en": "Never leave small infants unattended in twilight courtyards, lest the faceless mother envelope them in loving mists.",
    "image_url": "https://images.unsplash.com/photo-1509114397022-ed747cca3f65?auto=format&fit=crop&w=1200&q=80",
