    "lng": 139.7967,
    "story_th": "โคมไฟกระดาษโบราณที่มีอายุการใช้งานยาวนานจนเกิดรอยฉีกขาดตรงกลาง รอยขาดกลายเป็นปากกว้างที่มีฟันหยักและแลบลิ้นสีแดงยาวออกมา ด้านบนมีดวงตากลมโตหนึ่งดวงลืมขึ้นมาจ้องมองมนุษย์",
    "story_en": "A classic tsukumogami formed from a weathered paper lantern splitting horizontally to reveal a jagged mouth, long tongue, and single staring eye.",
    "folklore_history_th": "ตัวแทนที่โด่งดังที่สุดของสึคุโมะงามิ (วิญญาณสิ่งของ 100 ปี) ปรากฏในภาพพิมพ์อุกิโยะเอะ ละครคาบูกิ และบ้านผีสิงทั่วประเทศญี่ปุ่น เป็นผีขี้เล่นที่ไม่เป็นอันตรายถึงชีวิต",
    "folklore_history_en": "A staple tsukumogami depicted extensively in kabuki theater and Edo woodblock prints by artists such as Katsushika Hokusai.",
    "taboos_th": "ห้ามจุดไฟในโคมกระดาษเก่าที่มีรอยฉีกขาดกลางลำตัวโดยไม่ทำความสะอาดและขอขมา",
    "taboos_en": "Treat ancestral paper lanterns with care; torn paper left discarded in dark attics awakens the spirit within.",
