    "lat": 35.54,
    "lng": 133.23,
    "story_th": "ร่มกระดาษน้ำมันโบราณที่ถูกทิ้งขว้างจนกลายร่างเป็นโยไก มีดวงตากลมโตหนึ่งดวง มีปากกว้างแลบลิ้นยาว และมีขามนุษย์ข้างเดียวสวมรองเท้าเกี๊ยะ กระโดดดึ๋งๆ ไปตามถนนในวันที่ฝนตกพรำๆ",
    "story_en": "An iconic one-legged umbrella yokai with a single eye and protruding tongue, hopping merrily through rainy streets on a single geta-clad foot.",
    "folklore_history_th": "ได้รับความนิยมอย่างสูงในวัฒนธรรมร่วมสมัยของญี่ปุ่นผ่านผลงานการ์ตูนเรื่อง 'อสูรน้อยคิทาโร่' ของอาจารย์ชิเงรุ มิซึกิ เป็นสัญลักษณ์ของความผูกพันและคุณค่าของสิ่งของเครื่องใช้",
    "folklore_history_en": "Immortalized in modern Japanese pop culture by Shigeru Mizuki, representing the quintessential playful household artifact spirit.",
    "taboos_th": "ห้ามกางร่มกระดาษเก่าที่ถูกทิ้งขว้างไว้ในคืนที่ฝนตกพรำๆ",
    "taboos_en": "Never unfurl an abandoned oiled-paper umbrella found resting against temple eaves during twilight drizzles.",
