    "district_th": "บ้านร้างโบราณในแถบเกียวโต",
    "district_en": "Abandoned Machiya, Kyoto",
    "lat": 35.0116,
    "lng": 135.7681,
    "story_th": "ดวงตามนุษย์นับสิบถึงนับร้อยดวงที่ผุดขึ้นมาในช่องกระดาษที่ฉีกขาดของประตูบานเลื่อนโชจิในบ้านร้าง คอยกะพริบตาและจ้องมองผู้ที่พักอาศัยอยู่ในบ้านอย่างไม่ละสายตา",
    "story_en": "A yokai manifesting as countless unblinking human eyes peering through holes torn in shoji paper sliding doors inside neglected homes.",
    "folklore_history_th": "บันทึกในภาพพิมพ์ของ โทริยามะ เซกิเอน ในศตวรรษที่ 18 เล่าขานว่าพ่อค้าผู้ตระหนี่คนหนึ่งไม่ยอมเปลี่ยนกระดาษประตูโชจิที่ขาด จนตื่นขึ้นมาพบว่ามีดวงตานับร้อยกำลังจ้องมองตนอยู่",
    "folklore_history_en": "Drawn by Toriyama Sekien in his 1781 encyclopedia, illustrating the supernatural consequences of neglecting household repair through extreme thrift.",
    "taboos_th": "เมื่อพบรูกระดาษขาดบนประตูบานเลื่อนโชจิ ให้รีบนำกระดาษใหม่มาแปะซ่อมแซมทันที อย่าปล่อยทิ้งไว้ข้ามคืน",
    "taboos_en": "Mend torn holes in paper screens immediately; leaving empty apertures overnight invites unblinking spectral gazes.",
    "image_url": "https://images.unsplash.com/photo-1509114397022-ed747cca3f65?auto=format&fit=crop&w=1200&q=80",
    "sound_preset": "whisper",
