    "title_th": "อาชิอะไรยาชิกิ (คฤหาสน์เท้าปีศาจขอยืมล้างเท้าแห่งเอโดะ)",
    "title_en": "Ashiarai Yashiki (The Foot-Washing Mansion of Edo)",
    "category": "ghost",
    "province_th": "โตเกียว (ญี่ปุ่น)",
    "province_en": "Tokyo (Japan)",
    "district_th": "เขตสุมิดะ ย่านฮงโจ โตเกียว",
    "district_en": "Honjo, Sumida Ward, Tokyo",
    "lat": 35.7,
    "lng": 139.8,
    "story_th": "หนึ่งในเจ็ดสิ่งมหัศจรรย์แห่งฮงโจ ในยามดึก เพดานห้องพักของคฤหาสน์ซามูไรจะเปิดออก พร้อมกับมีขาและเท้าขนาดยักษ์ขนดกรกรุงรังและสกปรกยื่นตกลงมา ส่งเสียงคำรามก้องว่า 'ล้างเท้าให้ข้าเดี๋ยวนี้!'",
    "story_en": "One of the Seven Wonders of Honjo; a colossal, mud-caked hairy leg crashes through the ceiling at night demanding to be washed by the terrified homeowner.",
    "folklore_history_th": "หากเจ้าของบ้านนำน้ำและอ่างมาล้างทำความสะอาดให้ เท้ายักษ์จะหดกลับขึ้นไปบนเพดานอย่างสงบ แต่หากปฏิเสธ เท้าปีศาจจะกระทืบทำลายข้าวของในบ้านจนพังพินาศ",
    "folklore_history_en": "Celebrated in Edo-era urban lore; compliance with a basin of warm water satisfied the phantom limb, whereas refusal led to demolished tatami rooms.",
    "taboos_th": "หากมีเท้ายักษ์ทะลุเพดานตกลงมา ให้รีบเตรียมถังน้ำและแปรงขัดถูอย่างนอบน้อม ห้ามชักดาบฟันเด็ดขาด",
    "taboos_en": "Fetch a tub of water and wash the descending foot patiently; hostility causes violent structural destruction.",
    "image_url": "https://images.unsplash.com/photo-1473448912268-2022ce9509d8?auto=format&fit=crop&w=1200&q=80",
    "sound_preset": "whisper",
