    "title_th": "อุมิโบซุ (พระสงฆ์ยักษ์แห่งท้องทะเลลึกผู้คว่ำเรือ)",
    "title_en": "Umibozu (The Giant Sea Monk of the Pacific)",
    "category": "monster",
    "province_th": "อิวาเตะ (ญี่ปุ่น)",
    "province_en": "Iwate (Japan)",
    "district_th": "ชายฝั่งซันริคุและมหาสมุทรแปซิฟิก",
    "district_en": "Sanriku Coast & Pacific Waters",
    "lat": 39.5,
    "lng": 142,
    "story_th": "อสูรกายร่างยักษ์สีดำสนิท มีศีรษะกลมเกลี้ยงคล้ายพระสงฆ์แต่สูงตระหง่านหลายสิบเมตร โผล่พ้นผิวน้ำขึ้นมาในวันที่ทะเลนิ่งสนิท ดวงตาสีส้มเรืองแสง มันจะขอยืมถังตักน้ำจากกะลาสีเพื่อตักน้ำใส่เรือให้จมลงสู่ก้นทะเล",
    "story_en": "A colossal dark humanoid sea monster rising from calm Pacific waters with a smooth bald head and piercing glowing eyes, capsizing vessels with catastrophic waves.",
    "folklore_history_th": "กะลาสีเรือชาวญี่ปุ่นโบราณมีเคล็ดลับในการเอาชีวิตรอด โดยการมอบถังตักน้ำที่ถอดก้นออกให้อุมิโบซุ เมื่อมันพยายามตักน้ำ น้ำจะไหลทะลุออก ทำให้เรือมีเวลาแล่นหนีพ้น",
    "folklore_history_en": "One of the most feared maritime yokai; traditional crews carried bottomless barrels to trick the monster while beating a hasty retreat.",
    "taboos_th": "เมื่ออุมิโบซุโผล่ขึ้นมาขอยืมถังน้ำ ให้ยื่นถังที่เจาะก้นทะลุให้มันเท่านั้น ห้ามยื่นถังที่สมบูรณ์เด็ดขาด",
    "taboos_en": "Only hand a bottomless barrel to the Umibozu to exhaust its attempts to flood your deck.",
    "image_url": "https://images.unsplash.com/photo-1544717305-2782549b5136?auto=format&fit=crop&w=1200&q=80",
    "sound_preset": "water_spirit",
    "views_count": 12,
    "is_published": 1,
