    "title_th": "บาคุ (อสูรศักดิ์สิทธิ์กลืนกินฝันร้ายแห่งญี่ปุ่น)",
    "title_en": "Baku (The Sacred Nightmare-Devouring Chimera)",
    "category": "sacred",
    "province_th": "โตเกียว (ญี่ปุ่น)",
