    "lat": 34.3416,
    "lng": 108.9398,
    "story_th": "สุนัขสวรรค์สีดำยักษ์ที่มีหางเป็นดาวหาง สามารถเหาะเหินทะยานข้ามหมู่ดาว ออกล่ากลืนกินดวงอาทิตย์และดวงจันทร์จนเกิดปรากฏการณ์สุริยุปราคาและจันทรุปราคา",
    "story_en": "A mythical celestial hound of Chinese mythology famed for devouring the sun and moon during eclipses, accompanied by falling bolide meteors.",
    "folklore_history_th": "บันทึกในคัมภีร์ 'ซานไห่จิง' โบราณ เมื่อเกิดจันทรุปราคา ชาวจีนโบราณจะระดมตีฆ้อง ตีกลอง และจุดประทัดส่งเสียงดังสนั่นฟ้าเพื่อขับไล่เทียนโก่วให้คายดวงจันทร์ออกมา",
    "folklore_history_en": "Documented in the Classic of Mountains and Seas (Shanhaijing); communities historically beat gongs and fired firecrackers to force the celestial beast to disgorge the moon.",
    "taboos_th": "เมื่อเกิดคราสบนท้องฟ้า ให้ส่งเสียงเคาะโลหะหรือตีกลองเพื่อช่วยปลดปล่อยดวงจันทร์",
    "taboos_en": "Sound bronze bells and firecrackers during eclipses to drive the celestial hound away from heavenly bodies.",
