    "district_en": "Tian Shan Mountain Range",
    "lat": 40,
    "lng": 95,
    "story_th": "เทพอสูรบรรพกาลรูปร่างกลมคล้ายกระสอบสีแดงเพลิง มีขาหกขา มีปีกสี่ปีก ไม่มีใบหน้า ตา จมูก ปาก หรือหู แต่สามารถเข้าใจเสียงดนตรีและท่วงทำนองระบำรำฟ้อนได้อย่างลึกซึ้ง",
    "story_en": "A primordial entity of Chinese myth having a crimson sack-like body, six legs, four wings, and no facial orifices, yet residing in celestial harmony with song and dance.",
    "folklore_history_th": "บันทึกในคัมภีร์ซานไห่จิงโบราณ เป็นภาพสะท้อนของ 'ฮุ่นตุ้น' หรือความว่างเปล่าโกลาหลก่อนการกำเนิดฟ้าดินตามปรัชญาเต๋า",
    "folklore_history_en": "Detailed in the Shanhaijing as an embodiment of Hundun (primordial chaos) living in harmonic unity before the differentiation of senses.",
    "taboos_th": "ห้ามพยายามเจาะช่องตาหรือช่องปากให้แก่ตี้เจียง เพราะตามปรัชญาเต๋า ความพยายามจัดระเบียบความโกลาหลจะทำให้มันดับสูญ",
    "taboos_en": "Never attempt to carve facial features into the primal chaos, for forced order destroys primordial innocence.",
