    "title_th": "เหนียน (สัตว์ร้ายโบราณผู้เกลียดเสียงประทัดและสีแดง)",
    "title_en": "The Nian Beast of Lunar New Year",
    "category": "monster",
    "province_th": "ซานตง (จีน)",
    "province_en": "Shandong (China)",
    "district_th": "หมู่บ้านโบราณริมชายฝั่งทะเลจีนตะวันออก",
