    "lat": 36.0671,
    "lng": 120.3826,
    "story_th": "สัตว์ร้ายขนาดยักษ์ที่มีหัวคล้ายสิงโตและมีเขาแหลม อาศัยอยู่ใต้ก้นทะเลลึก ทุกคืนสิ้นปีจะขึ้นมาบนบกเพื่อจับผู้คนและปศุสัตว์กินเป็นอาหาร จนกระทั่งชาวบ้านค้นพบว่ามันหวาดกลัวสีแดง แสงไฟ และเสียงระเบิดดังกึกก้อง",
    "story_en": "A ferocious predatory sea monster that emerged on New Year's Eve to feast on villagers until terrified by the color red, bright lanterns, and exploding firecrackers.",
    "folklore_history_th": "เป็นที่มาของประเพณีเทศกาลตรุษจีนที่สืบทอดมานับพันปี ทั้งการสวมเสื้อผ้าสีแดง ติดกระดาษคำอวยพรสีแดงหน้าบ้าน และจุดประทัดเสียงดังสนั่นเพื่อ 'กว้าเหนียน' (ข้ามพ้นปีและขับไล่เหนียน)",
    "folklore_history_en": "The origin myth of Chinese Lunar New Year customs: hanging red paper couplets, illuminating lanterns, and setting off firecrackers to celebrate surviving the Nian.",
    "taboos_th": "ในคืนวันสิ้นปี ห้ามดับตะเกียงไฟในเรือน และต้องติดกระดาษสีแดงไว้ที่บานประตูหน้าบ้าน",
    "taboos_en": "Keep doors adorned with scarlet banners and maintain lanterns lit throughout New Year's Eve.",
