    "title_th": "ทัลกยัลกวิชิน (ผีไข่ไร้หน้ามรณะแห่งเกาหลี)",
    "title_en": "Dalgyal Gwisin (The Egg Ghost of Korean Lore)",
    "category": "ghost",
    "province_th": "คังวอน (เกาหลีใต้)",
