    "id": "pin-bahamut-arabian",
    "title_th": "บาฮามุต (มหาปลาวาฬยักษ์ผู้รองรับผืนพิภพและจักรวาล)",
    "title_en": "Bahamut (The Cosmic Leviathan of the Abyss)",
    "category": "sacred",
    "province_th": "มักกะฮ์ (ซาอุดีอาระเบีย)",
