    "id": "pin-nasnas-yemen",
    "title_th": "นาสนัส (อสุรกายครึ่งซีกกระโดดขาเดียวแห่งเยเมน)",
    "title_en": "Nasnas (The Half-Human Jinn of Yemen)",
    "category": "monster",
    "province_th": "ฮัดราเมาต์ (เยเมน)",
